class Solution{
public:
    void reverse(int arr[], int n){
        // using 2 pointer method
        // one pointer on the left -> index 0
        // another pointer on the right -> index n-1
        // swap(left,right)
        // left++
        // right--
        // we'll stop when left = right

        int left = 0;
        int right = n-1;

        while(left < right){
            swap(arr[left], arr[right]);
            left ++;
            right --;
        }        
    }
};

```

